import React from 'react';
import Highcharts from 'highcharts';
import HighchartsReact from 'highcharts-react-official';

export default function Summary({ orders, expenses }) {
  const groupByDate = (data) =>
    data.reduce((acc, item) => {
      if (!item?.date || isNaN(item?.amount)) return acc;
      acc[item.date] = (acc[item.date] || 0) + Number(item.amount);
      return acc;
    }, {});

  const orderTotals = groupByDate(orders || []);
  const expenseTotals = groupByDate(expenses || []);

  const allDates = Array.from(
    new Set([...Object.keys(orderTotals), ...Object.keys(expenseTotals)])
  ).sort();

  const orderChartData = allDates.map((date) => orderTotals[date] || 0);
  const expenseChartData = allDates.map((date) => expenseTotals[date] || 0);

  const totalOrderAmount = orders.reduce((sum, o) => sum + (o.amount || 0), 0);
  const totalExpenseAmount = expenses.reduce((sum, e) => sum + (e.amount || 0), 0);
  const net = totalOrderAmount - totalExpenseAmount;

  const chartOptions = {
    chart: {
      type: 'column'
    },
    title: {
      text: 'Orders vs Expenses'
    },
    xAxis: {
      categories: allDates.map(date => new Date(date).toDateString())
    },
    yAxis: {
      title: {
        text: 'Amount (₹)'
      }
    },
    series: [
      {
        name: 'Orders',
        data: orderChartData,
        color: '#28a745'
      },
      {
        name: 'Expenses',
        data: expenseChartData,
        color: '#dc3545'
      }
    ]
  };

  return (
    <div className="card p-3">
      <h5>Summary</h5>

      <HighchartsReact highcharts={Highcharts} options={chartOptions} />

      <div className="mt-4">
        <h6>Totals</h6>
        <table className="table table-bordered">
          <tbody>
            <tr>
              <th>Total Orders</th>
              <td>{`₹${totalOrderAmount.toFixed(2)}`}</td>
            </tr>
            <tr>
              <th>Total Expenses</th>
              <td>{`₹${totalExpenseAmount.toFixed(2)}`}</td>
            </tr>
            <tr>
              <th>Net</th>
              <td style={{ color: net >= 0 ? 'green' : 'red' }}>
                {`₹${net.toFixed(2)}`}
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}
