import React, { useState,useRef } from 'react';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';
import { Tag } from 'primereact/tag';
import { InputText } from 'primereact/inputtext';
import { InputNumber } from 'primereact/inputnumber';
import { Button } from 'primereact/button';
export default function ExpenseList({ data }) {
  const [expandedRows, setExpandedRows] = useState([]);

  const totalAll = data.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0);
 const tableRef = useRef(null);
  const amountTemplate = (rowData) => {
    const amount = parseFloat(rowData.amount);
    return isNaN(amount) ? '₹0.00' : `₹${amount.toFixed(2)}`;
  };

  const onCellEditComplete = (e) => {
    const { rowData, newValue, field, originalEvent } = e;
    if (field === 'amount' && (isNaN(newValue) || newValue < 0)) {
      originalEvent.preventDefault();
      return;
    }
    rowData[field] = field === 'amount' ? parseFloat(newValue) : newValue;
  };
    const exportCSV = () => {
    if (tableRef.current) {
      tableRef.current.exportCSV();
    }
  };


  const formatDate = (dateStr) => {
    try {
      const d = new Date(dateStr);
      return isNaN(d.getTime())
        ? 'Invalid Date'
        : d.toLocaleDateString('en-IN', {
            weekday: 'short',
            year: 'numeric',
            month: 'short',
            day: 'numeric',
          });
    } catch {
      return 'Invalid Date';
    }
  };

  const createHeaderTemplate = (allData) => (groupRow) => {
    const groupDate = groupRow.date;
    const dayTotal = allData
      .filter((item) => item.date === groupDate)
      .reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0);

    const formatted = formatDate(groupDate);

    return (
      <React.Fragment>
        <span className="fw-bold">{formatted}</span>
        <span style={{ marginLeft: 'auto', float: 'right' }} className="text-danger fw-bold">
          Total: ₹{dayTotal.toFixed(2)}
        </span>
      </React.Fragment>
    );
  };

  return (
    <div className="card p-3 mb-3">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h5 className="mb-0">Expenses List</h5>
        <Tag severity="danger" value={`Total: ₹${totalAll.toFixed(2)}`} />
         <Button label="Export CSV" icon="pi pi-file" className="p-button-sm" onClick={exportCSV} />
      </div>

      <DataTable
        ref={tableRef}
        value={data}
        rowGroupMode="subheader"
        groupRowsBy="date"
        sortField="date"
        sortOrder={-1}
        expandableRowGroups
        expandedRows={expandedRows}
        onRowToggle={(e) => setExpandedRows(e.data)}
        rowGroupHeaderTemplate={createHeaderTemplate(data)}
        responsiveLayout="scroll"
        scrollable
        editMode="cell"
        className="p-datatable-sm"
      >
        <Column field="date" header="Date" className="d-none" />

        <Column
          field="desc"
          header="Description"
          sortable
          editor={(options) => (
            <InputText
              value={options.value}
              onChange={(e) => options.editorCallback(e.target.value)}
            />
          )}
        />

        <Column
          field="amount"
          header="Amount"
          body={amountTemplate}
          sortable
          editor={(options) => (
            <InputNumber
              value={options.value}
              onValueChange={(e) => options.editorCallback(e.value)}
              mode="currency"
              currency="INR"
              locale="en-IN"
              minFractionDigits={2}
            />
          )}
          onCellEditComplete={onCellEditComplete}
        />
      </DataTable>
    </div>
  );
}
